using System.Collections.Generic;
using System.Net;
using System.Text;

namespace UI_Desktop.Store;

internal static class StoreOrderHistoryHtmlBuilder
{
	public static string BuildDocument(DesktopAccountResponse account, StoreWebHomeContext context)
	{
		return $"<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n<head>\r\n<meta charset=\"utf-8\" />\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n<title>Lịch sử mua hàng NestG</title>\r\n<style>{BuildStyles()}{StoreWarpHeaderHtml.Styles}{StoreWindowsUpdateHeaderHtml.Styles}{StoreSteamConnectionHeaderHtml.Styles}{StoreSupportContactHeaderHtml.Styles}</style>\r\n</head>\r\n<body>\r\n<div class=\"orders-shell\">\r\n    <header class=\"orders-chrome\" data-drag-region>\r\n        <div class=\"nestg-brand-warp\">\r\n            <div class=\"brand-cluster\">\r\n                <span class=\"brand-mark\">N</span>\r\n                <span class=\"brand-copy\"><strong>NestG</strong><small>Lịch sử mua hàng</small></span>\r\n            </div>\r\n            {StoreWarpHeaderHtml.Render()}\r\n            {StoreWindowsUpdateHeaderHtml.Render()}\r\n            {StoreSteamConnectionHeaderHtml.Render()}\r\n        </div>\r\n        <nav class=\"orders-nav\">\r\n            <button type=\"button\" data-host-action=\"backHome\">Cửa hàng</button>\r\n            <button type=\"button\" data-host-action=\"openProfile\">Cá nhân</button>\r\n            <button type=\"button\" data-host-action=\"openWalletTopup\">Nạp ví</button>\r\n        </nav>\r\n        <div class=\"nestg-header-account\">\r\n            {StoreSupportContactHeaderHtml.Render()}\r\n            {StoreAccountMenuHtml.Build(account, "orders", context.NotificationUnreadCount)}\r\n        </div>\r\n        <div class=\"window-controls\">\r\n            <button type=\"button\" class=\"window-button\" data-host-action=\"minimize\" aria-label=\"Thu nhỏ cửa sổ\">-</button>\r\n            <button type=\"button\" class=\"window-button\" data-host-action=\"toggleMaximize\" aria-label=\"Phóng to hoặc khôi phục cửa sổ\">&#9633;</button>\r\n            <button type=\"button\" class=\"window-button is-close\" data-host-action=\"close\" aria-label=\"Đóng cửa sổ\">&#215;</button>\r\n        </div>\r\n    </header>\r\n\r\n    <main class=\"orders-content\">\r\n        <section class=\"orders-hero\">\r\n            <div>\r\n                <span class=\"eyebrow\">TÀI KHOẢN NESTG</span>\r\n                <h1>Lịch sử mua hàng</h1>\r\n                <p>Theo dõi các đơn hàng, giao dịch nạp ví và tiếp tục thanh toán những phiếu đang chờ.</p>\r\n            </div>\r\n            <div class=\"orders-summary\">\r\n                <span>Tổng đơn hàng</span>\r\n                <strong>{account.TotalOrders.ToString("N0")}</strong>\r\n                <small>{account.PaidOrders.ToString("N0")} đã thanh toán · {account.PendingOrders.ToString("N0")} đang chờ</small>\r\n            </div>\r\n        </section>\r\n\r\n        <section class=\"metric-grid\">\r\n            {Metric("Tất cả", account.TotalOrders, "Toàn bộ lịch sử")}\r\n            {Metric("Đã thanh toán", account.PaidOrders, "Đơn đã hoàn tất")}\r\n            {Metric("Đang chờ", account.PendingOrders, "Có thể thanh toán tiếp")}\r\n            {Metric("Số dư ví", account.WalletBalanceText, "Ví NestG hiện tại")}\r\n        </section>\r\n\r\n        <section class=\"orders-panel\">\r\n            <div class=\"orders-toolbar\">\r\n                <div class=\"filter-group\">\r\n                    <button type=\"button\" class=\"is-active\" data-order-filter=\"all\">Tất cả</button>\r\n                    <button type=\"button\" data-order-filter=\"pending\">Đang chờ</button>\r\n                    <button type=\"button\" data-order-filter=\"paid\">Đã thanh toán</button>\r\n                    <button type=\"button\" data-order-filter=\"other\">Trạng thái khác</button>\r\n                </div>\r\n                <label class=\"search-box\">\r\n                    <input type=\"search\" data-order-search placeholder=\"Tìm mã đơn hoặc nội dung...\" />\r\n                </label>\r\n                <button type=\"button\" class=\"refresh-button\" data-host-action=\"refreshOrderHistory\">Làm mới</button>\r\n            </div>\r\n            <div class=\"orders-list\" data-orders-list>\r\n                {RenderOrders(account.Orders)}\r\n            </div>\r\n            <div class=\"empty-state\" data-orders-empty hidden>Không có đơn hàng phù hợp.</div>\r\n            <div class=\"orders-pagination\" data-orders-pagination hidden>\r\n                <span data-pagination-summary></span>\r\n                <div class=\"pagination-controls\">\r\n                    <button type=\"button\" data-page-prev>Trước</button>\r\n                    <div class=\"pagination-pages\" data-pagination-pages></div>\r\n                    <button type=\"button\" data-page-next>Sau</button>\r\n                </div>\r\n            </div>\r\n        </section>\r\n    </main>\r\n</div>\r\n{BuildLoadingOverlay()}\r\n{BuildCheckoutModal()}\r\n<script>{BuildScript()}</script>\r\n</body>\r\n</html>";
	}

	private static string RenderOrders(IReadOnlyList<DesktopAccountOrderResponse> orders)
	{
		if (orders.Count == 0)
		{
			return "<div class=\"empty-state\">Bạn chưa có đơn hàng nào.</div>";
		}
		StringBuilder stringBuilder = new StringBuilder();
		foreach (DesktopAccountOrderResponse order in orders)
		{
			string text = ResolveStatusGroup(order.Status);
			string text2 = ((text == "paid") ? "is-paid" : ((!(text == "pending")) ? "is-other" : "is-pending"));
			string value = text2;
			bool flag = text == "pending" && !string.IsNullOrWhiteSpace(order.OrderCode);
			string value2 = $"{order.OrderCode} {order.LineSummary} {order.StatusText}".ToLowerInvariant();
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(448, 9, stringBuilder2);
			handler.AppendLiteral("<article class=\"order-card\" data-order-card data-status-group=\"");
			handler.AppendFormatted(text);
			handler.AppendLiteral("\" data-search=\"");
			handler.AppendFormatted(Attr(value2));
			handler.AppendLiteral("\">\r\n    <div class=\"order-main\">\r\n        <div class=\"order-heading\">\r\n            <span class=\"order-code\">");
			handler.AppendFormatted(Html(order.OrderCode));
			handler.AppendLiteral("</span>\r\n            <span class=\"status-badge ");
			handler.AppendFormatted(value);
			handler.AppendLiteral("\">");
			handler.AppendFormatted(Html(order.StatusText));
			handler.AppendLiteral("</span>\r\n        </div>\r\n        <h2>");
			handler.AppendFormatted(Html(order.LineSummary));
			handler.AppendLiteral("</h2>\r\n        <p>Được tạo lúc ");
			handler.AppendFormatted(Html(order.CreatedAtText));
			handler.AppendLiteral("</p>\r\n    </div>\r\n    <div class=\"order-side\">\r\n        <span>Tổng thanh toán</span>\r\n        <strong>");
			handler.AppendFormatted(Html(order.TotalAmountText));
			handler.AppendLiteral("</strong>\r\n        ");
			handler.AppendFormatted(flag ? $"<button type=\"button\" data-order-checkout=\"{Attr(order.OrderCode)}\">{Html(string.IsNullOrWhiteSpace(order.ActionLabel) ? "Thanh toán tiếp" : order.ActionLabel)}</button>" : string.Empty);
			handler.AppendLiteral("\r\n    </div>\r\n</article>");
			stringBuilder2.Append(ref handler);
		}
		return stringBuilder.ToString();
	}

	private static string ResolveStatusGroup(string? status)
	{
		switch (status?.Trim().ToLowerInvariant())
		{
		case "pending_payment":
		case "processing":
			return "pending";
		case "paid":
			return "paid";
		default:
			return "other";
		}
	}

	private static string Metric(string label, int value, string hint)
	{
		return Metric(label, value.ToString("N0"), hint);
	}

	private static string Metric(string label, string value, string hint)
	{
		return $"<article class=\"metric-card\">\r\n    <span>{Html(label)}</span><strong>{Html(value)}</strong><small>{Html(hint)}</small>\r\n</article>";
	}

