ght:68px; display:grid; grid-template-columns:minmax(0,1fr) 280px auto; gap:14px; align-items:center; padding:12px 16px; border-bottom:1px solid rgba(102,192,244,.12); }\r\n.filter-group { display:flex; flex-wrap:wrap; gap:8px; }\r\n.filter-group button,.refresh-button { min-height:38px; padding:0 14px; border:1px solid rgba(102,192,244,.18); border-radius:4px; background:rgba(102,192,244,.06); color:#a8c7da; font-size:12px; font-weight:850; }\r\n.filter-group button.is-active { border-color:rgba(102,192,244,.58); background:rgba(102,192,244,.17); color:#e8f8ff; }\r\n.search-box input { width:100%; height:40px; padding:0 13px; border:1px solid rgba(102,192,244,.2); border-radius:4px; outline:0; background:rgba(5,16,25,.7); color:#edf6ff; }\r\n.search-box input:focus { border-color:#66c0f4; }\r\n.orders-list { display:grid; gap:12px; padding:16px; }\r\n.order-card { display:grid; grid-template-columns:minmax(0,1fr) 220px; gap:18px; padding:18px; border:1px solid rgba(102,192,244,.1); border-radius:6px; background:rgba(5,16,25,.58); }\r\n.order-heading { display:flex; flex-wrap:wrap; align-items:center; gap:10px; }\r\n.order-code { color:#9edfff; font-size:12px; font-weight:900; letter-spacing:.05em; }\r\n.status-badge { min-height:27px; display:inline-flex; align-items:center; padding:0 10px; border-radius:999px; font-size:11px; font-weight:900; }\r\n.status-badge.is-paid { border:1px solid rgba(155,211,61,.34); background:rgba(155,211,61,.1); color:#d6ff9b; }\r\n.status-badge.is-pending { border:1px solid rgba(255,198,92,.34); background:rgba(255,198,92,.09); color:#ffd58c; }\r\n.status-badge.is-other { border:1px solid rgba(160,177,194,.25); background:rgba(160,177,194,.08); color:#b8c9d7; }\r\n.order-main h2 { margin:12px 0 5px; color:#eef8ff; font-size:18px; }\r\n.order-main p { margin:0; color:#7f96a8; font-size:12px; }\r\n.order-side { display:flex; flex-direction:column; align-items:flex-end; justify-content:center; text-align:right; }\r\n.order-side>span { color:#8199aa; font-size:11px; text-transform:uppercase; }\r\n.order-side>strong { margin-top:6px; color:#dfffb5; font-size:23px; }\r\n.order-side button { min-width:150px; min-height:40px; margin-top:14px; border:1px solid rgba(190,240,111,.25); border-radius:4px; background:linear-gradient(180deg,#9bd33d,#75a920); color:#fff; font-weight:900; }\r\n.empty-state { padding:28px; color:#8097a9; text-align:center; }\r\n.orders-pagination { min-height:62px; display:flex; align-items:center; justify-content:space-between; gap:16px; padding:12px 16px 16px; border-top:1px solid rgba(102,192,244,.12); color:#8fa6b8; font-size:12px; }\r\n.pagination-controls { display:flex; align-items:center; gap:8px; }\r\n.pagination-pages { display:flex; align-items:center; gap:6px; }\r\n.pagination-controls button,.pagination-pages button { min-width:38px; min-height:36px; padding:0 12px; border:1px solid rgba(102,192,244,.18); border-radius:4px; background:rgba(102,192,244,.07); color:#b9d8ec; font-size:12px; font-weight:900; }\r\n.pagination-controls button:hover:not(:disabled),.pagination-pages button:hover:not(:disabled) { border-color:rgba(102,192,244,.48); background:rgba(102,192,244,.15); color:#fff; }\r\n.pagination-controls button:disabled,.pagination-pages button:disabled { cursor:default; opacity:.45; }\r\n.pagination-pages button.is-active { border-color:rgba(155,211,61,.46); background:rgba(155,211,61,.15); color:#e4ffbd; }\r\n.checkout-modal { position:fixed; inset:0; z-index:80; display:grid; place-items:center; padding:28px; background:rgba(2,7,12,.72); backdrop-filter:blur(10px); }\r\n.checkout-dialog { width:min(980px,calc(100vw - 56px)); max-height:calc(100vh - 56px); display:grid; grid-template-rows:auto minmax(0,1fr); overflow:hidden; border:1px solid rgba(102,192,244,.24); border-radius:8px; background:linear-gradient(180deg,rgba(15,31,46,.98),rgba(6,15,24,.98)); box-shadow:0 34px 90px rgba(0,0,0,.48); }\r\n.checkout-head { min-height:62px; display:flex; align-items:center; justify-content:space-between; gap:16px; padding:16px 18px; border-bottom:1px solid rgba(102,192,244,.14); }\r\n.checkout-head h2 { margin:0; font-size:22px; }\r\n.checkout-close { width:34px; height:34px; border:1px solid rgba(102,192,244,.18); border-radius:4px; background:rgba(102,192,244,.08); }\r\n.checkout-body { overflow:auto; padding:18px; }\r\n.checkout-grid { display:grid; grid-template-columns:330px minmax(0,1fr); gap:18px; }\r\n.checkout-card { border:1px solid rgba(102,192,244,.16); border-radius:7px; background:rgba(8,18,29,.78); padding:18px; }\r\n.checkout-card h3 { margin:0 0 14px; font-size:20px; }\r\n.checkout-status { margin:-4px 0 14px; color:#ffc65c; font-weight:900; }\r\n.checkout-status.is-paid { color:#bfff76; }\r\n.checkout-qr { display:grid; place-items:center; min-height:292px; border:1px solid rgba(102,192,244,.18); border-radius:6px; background:#fff; }\r\n.checkout-qr img { width:min(280px,100%); aspect-ratio:1; object-fit:contain; }\r\n.checkout-qr-fallback { color:#13202c; font-weight:900; text-align:center; padding:22px; }\r\n.checkout-total-label { display:block; margin-top:14px; color:#8fa6b8; font-size:12px; text-transform:uppercase; }\r\n.checkout-total { display:block; margin-top:4px; color:#ffd774; font-size:30px; font-weight:950; }\r\n.checkout-facts { display:grid; gap:12px; margin:0; }\r\n.checkout-facts div { display:grid; grid-template-columns:150px minmax(0,1fr); gap:14px; }\r\n.checkout-facts dt { color:#8fa6b8; }\r\n.checkout-facts dd { margin:0; color:#eef8ff; font-weight:850; overflow-wrap:anywhere; }\r\n.checkout-summary { display:grid; gap:10px; }\r\n.checkout-row { display:flex; justify-content:space-between; gap:16px; color:#b7ccdc; }\r\n.checkout-row strong { color:#fff; }\r\n.checkout-row.is-total { padding-top:10px; border-top:1px solid rgba(102,192,244,.14); color:#fff; font-weight:950; }\r\n.checkout-row.is-total strong { color:#ffd774; font-size:20px; }\r\n.checkout-items { display:grid; gap:8px; }\r\