lumns:1fr}.order-side{align-items:flex-start;text-align:left}.orders-pagination{align-items:flex-start;flex-direction:column}.checkout-grid{grid-template-columns:1fr}.checkout-facts div{grid-template-columns:1fr} }";
	}

	private static string BuildCheckoutModal()
	{
		return "<div class=\"checkout-modal\" data-checkout-modal hidden>\r\n    <div class=\"checkout-dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"checkoutTitle\">\r\n        <header class=\"checkout-head\">\r\n            <h2 id=\"checkoutTitle\" data-checkout-title>Thanh toán đơn hàng</h2>\r\n            <button type=\"button\" class=\"checkout-close\" data-checkout-close>&#215;</button>\r\n        </header>\r\n        <div class=\"checkout-body\">\r\n            <div class=\"checkout-grid\">\r\n                <section class=\"checkout-card\">\r\n                    <h3>QR thanh toán</h3>\r\n                    <div class=\"checkout-status\" data-checkout-status-title></div>\r\n                    <div class=\"checkout-qr\">\r\n                        <img data-checkout-qr-image alt=\"QR thanh toán\" />\r\n                        <div class=\"checkout-qr-fallback\" data-checkout-qr-fallback hidden>Không có mã QR cho giao dịch này.</div>\r\n                    </div>\r\n                    <span class=\"checkout-total-label\">Tổng cần thanh toán</span>\r\n                    <strong class=\"checkout-total\" data-checkout-total></strong>\r\n                </section>\r\n                <div class=\"checkout-stack\">\r\n                    <section class=\"checkout-card\">\r\n                        <h3>Thông tin chuyển khoản</h3>\r\n                        <dl class=\"checkout-facts\">\r\n                            <div><dt>Ngân hàng</dt><dd data-checkout-bank></dd></div>\r\n                            <div><dt>Số tài khoản</dt><dd data-checkout-account-number></dd></div>\r\n                            <div><dt>Chủ tài khoản</dt><dd data-checkout-account-name></dd></div>\r\n                            <div><dt>Nội dung CK</dt><dd data-checkout-transfer-content></dd></div>\r\n                            <div><dt>Hết hạn</dt><dd data-checkout-expires></dd></div>\r\n                        </dl>\r\n                    </section>\r\n                    <section class=\"checkout-card\">\r\n                        <h3>Tổng hợp đơn hàng</h3>\r\n                        <div class=\"checkout-summary\">\r\n                            <div class=\"checkout-row\"><span>Tạm tính</span><strong data-checkout-subtotal></strong></div>\r\n                            <div class=\"checkout-row\"><span>Giảm giá</span><strong data-checkout-discount></strong></div>\r\n                            <div class=\"checkout-row\"><span>Voucher</span><strong data-checkout-voucher></strong></div>\r\n                            <div class=\"checkout-row is-total\"><span>Tổng thanh toán</span><strong data-checkout-summary-total></strong></div>\r\n                        </div>\r\n                    </section>\r\n                    <section class=\"checkout-card\">\r\n                        <h3>Sản phẩm trong đơn</h3>\r\n                        <div class=\"checkout-items\" data-checkout-items></div>\r\n                    </section>\r\n                    <div class=\"checkout-actions\">\r\n                        <button type=\"button\" class=\"checkout-refresh\" data-checkout-refresh>Làm mới trạng thái</button>\r\n                        <button type=\"button\" class=\"checkout-confirm\" data-checkout-confirm hidden>Đã hiểu</button>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"toast-host\" data-toast-host></div>";
	}

	private static string BuildLoadingOverlay()
	{
		return "<div class=\"app-loading-overlay\" data-app-loading hidden>\r\n    <div class=\"app-loading-dialog\"><span class=\"app-loading-kicker\">NESTG STORE</span><h2 data-app-loading-title>Đang xử lý</h2><p data-app-loading-message>Vui lòng chờ trong giây lát.</p></div>\r\n</div>";
	}

	private static string BuildScript()
	{
		return "(() => {\r\n    const post = message => window.chrome?.webview?.postMessage(message);\r\n" + StoreAccountMenuHtml.Script + "\r\n    const cards = Array.from(document.querySelectorAll('[data-order-card]'));\r\n    const search = document.querySelector('[data-order-search]');\r\n    const empty = document.querySelector('[data-orders-empty]');\r\n    const loading = document.querySelector('[data-app-loading]');\r\n    const pagination = document.querySelector('[data-orders-pagination]');\r\n    const paginationSummary = document.querySelector('[data-pagination-summary]');\r\n    const paginationPages = document.querySelector('[data-pagination-pages]');\r\n    const pagePrev = document.querySelector('[data-page-prev]');\r\n    const pageNext = document.querySelector('[data-page-next]');\r\n    const toastHost = document.querySelector('[data-toast-host]');\r\n    const checkoutModal = document.querySelector('[data-checkout-modal]');\r\n    const checkoutQrImage = document.querySelector('[data-checkout-qr-image]');\r\n    const checkoutQrFallback = document.querySelector('[data-checkout-qr-fallback]');\r\n    const checkoutRefresh = document.querySelector('[data-checkout-refresh]');\r\n    const checkoutConfirm = document.querySelector('[data-checkout-confirm]');\r\n    const checkoutItems = document.querySelector('[data-checkout-items]');\r\n    const pageSize = 5;\r\n    let filter = 'all';\r\n    let currentPage = 1;\r\n    let activeCheckoutOrderCode = '';\r\n    let checkoutPollTimer = 0;\r\n\r\n    function setText(selector, value) {\r\n        const element = document.querySelector(selector);\r\n        if (element) element.textContent = value || '';\r\n    }\r\n\r\n    function showToast(message) {\r\n        if (!toastHost || !message) return;\r\n        const toast = document.createElement('div');\r\n        toast.className = 'toast';\r\n        toast.textContent = message;\r\n        toastHost.append(toast);\r\n        window.setTimeout(() => toast.remove(), 3600);\r\n    }\r\n\r\n    function getFilteredCards() {\r\n        const query = String(search?.value || '').trim().toLowerCase();\r\n        return cards.filter(card => {\r\n            const matchesFilter = filter === 'all' || card.dataset.statusGroup === filter;\r\n            const matchesSearch = !query || String(card.dataset.search || '').includes(query);\r\n            return matchesFilter && matchesSearch;\r\n        });\r\n    }\r\n\r\n    function renderPagination(filteredCards) {\r\n        const total = filteredCards.length;\r\n        const totalPages = Math.max(1, Math.ceil(total / pageSize));\r\n        currentPage = Math.max(1, Math.min(currentPage, totalPages));\r\n        const start = total === 0 ? 0 : (currentPage - 1) * pageSize + 1;\r\n        const end = Math.min(total, currentPage * pageSize);\r\n\r\n        if (paginationSummary) {\r\n            paginationSummary.textContent = total === 0\r\n                ? 'Không có đơn hàng'\r\n                : `Hiển thị ${start}-${end} trong ${total} đơn hàng`;\r\n        }\r\n\r\n        if (pagination) {\r\n            pagination.hidden = total <= pageSize;\r\n        }\r\n\r\n        if (pagePrev) pagePrev.disabled = currentPage <= 1;\r\n        if (pageNext) pageNext.disabled = currentPage >= totalPages;\r\n        if (!paginationPages) return;\r\n\r\n        paginationPages.textContent = '';\r\n        const pages = [];\r\n        for (let page = 1; page <= totalPages; page += 1) {\r\n            if (page === 1 || page === totalPages || Math.abs(page - currentPage) <= 1) {\r\n                pages.push(page);\r\n            }\r\n        }\r\n\r\n        let previous = 0;\r\n        pages.forEach(page => {\r\n            if (previous && page - previous > 1) {\r\n                const gap = document.createElement('span');\r\n                gap.textContent = '...';\r\n                gap.style.padding = '0 4px';\r\n                paginationPages.append(gap);\r\n            }\r\n\r\n            const button = document.createElement('button');\r\n            button.type = 'button';\r\n            button.textContent = String(page);\r\n            button.classList.toggle('is-active', page === currentPage);\r\n            button.disabled = page === currentPage;\r\n            button.addEventListener('click', () => {\r\n                currentPage = page;\r\n                applyFilters(false);\r\n            });\r\n            paginationPages.append(button);\r\n            previous = page;\r\n        });\r\n    }\r\n\r\n    function applyFilters(resetPage = true) {\r\n        if (resetPage) currentPage = 1;\r\n        const filteredCards = getFilteredCards();\r\n        const visibleSet = new Set(filteredCards);\r\n        const startIndex = (currentPage - 1) * pageSize;\r\n        const endIndex = startIndex + pageSize;\r\n        const pageCards = new Set(filteredCards.slice(startIndex, endIndex));\r\n\r\n        cards.forEach(card => {\r\n            card.hidden = !visibleSet.has(card) || !pageCards.has(card);\r\n        });\r\n\r\n        if (empty) empty.hidden = filteredCards.length !== 0;\r\n        renderPagination(filteredCards);\r\n    }\r\n\r\n    document.addEventListener('click', event => {\r\n        const target = event.target instanceof Element ? event.target : null;\r\n        if (!target) return;\r\n        if (target.closest('[data-account-toggle]')) {\r\n            setAccountMenuOpen(Boolean(accountMenu?.hidden));\r\n            return;\r\n        }\r\n        if (!target.closest('[data-account-menu]')) {\r\n            setAccountMenuOpen(false);\r\n        }\r\n        const filterButton = target.closest('[data-order-filter]');\r\n        if (filterButton) {\r\n            filter = filterButton.getAttribute('data-order-filter') || 'all';\r\n            document.querySelectorAll('[data-order-filter]').forEach(button => button.classList.toggle('is-active', button === filterButton));\r\n            applyFilters(true);\r\n            return;\r\n        }\r\n        const checkoutButton = target.closest('[data-order-checkout]');\r\n        if (checkoutButton) {\r\n            checkoutButton.disabled = true;\r\n            checkoutButton.textContent = 'Đang mở...';\r\n            post({ type: 'openOrderCheckout', orderCode: checkoutButton.getAttribute('data-order-checkout') });\r\n            return;\r\n        }\r\n        const action = target.closest('[data-host-action]');\r\n        if (!action) return;\r\n        post({ type: action.getAttribute('data-host-action') });\r\n    });\r\n\r\n    search?.addEventListener('input', () => applyFilters(true));\r\n\r\n    pagePrev?.addEventListener('click', () => {\r\n        currentPage = Math.max(1, currentPage - 1);\r\n        applyFilters(false);\r\n    });\r\n\r\n    pageNext?.addEventListener('click', () => {\r\n        currentPage += 1;\r\n        applyFilters(false);\r\n    });\r\n\r\n    applyFilters(true);\r\n    \r\n    function renderCheckoutItems(items) {\r\n        if (!checkoutItems) return;\r\n        checkoutItems.textContent = '';\r\n        const list = Array.isArray(items) ? items : [];\r\n        if (list.length === 0) {\r\n            const emptyItem = document.createElement('div');\r\n            emptyItem.className = 'empty-state';\r\n            emptyItem.textContent = 'Không có sản phẩm trong đơn.';\r\n            checkoutItems.append(emptyItem);\r\n            return;\r\n        }\r\n\r\n        list.forEach(item => {\r\n            const row = document.createElement('div');\r\n            row.className = 'checkout-item';\r\n            const info = document.createElement('div');\r\n            const name = document.createElement('strong');\r\n            name.textContent = item.name || 'Sản phẩm NestG';\r\n            const meta = document.createElement('small');\r\n            meta.textContent = `${item.versionName || 'Standard'} · x${item.quantity || 1}`;\r\n            info.append(name, meta);\r\n            const total = document.createElement('strong');\r\n            total.textContent = item.lineTotalText || item.unitPriceText || '';\r\n            row.append(info, total);\r\n            checkoutItems.append(row);\r\n        });\r\n    }\r\n\r\n    function updateCheckoutStatus(payload) {\r\n        if (!payload) return;\r\n        setText('[data-checkout-status-title]', payload.statusTitle || '');\r\n        const statusTitle = document.querySelector('[data-checkout-status-title]');\r\n        statusTitle?.classList.toggle('is-paid', Boolean(payload.isPaid));\r\n        if (payload.isPaid) {\r\n            window.clearInterval(checkoutPollTimer);\r\n            checkoutPollTimer = 0;\r\n            if (checkoutRefresh) {\r\n                checkoutRefresh.disabled = true;\r\n                checkoutRefresh.textContent = 'Đã thanh toán';\r\n            }\r\n            if (checkoutConfirm) checkoutConfirm.hidden = false;\r\n            showToast(payload.statusDescription || 'Đơn hàng đã được thanh toán.');\r\n        } else if (checkoutRefresh) {\r\n            checkoutRefresh.disabled = false;\r\n            checkoutRefresh.textContent = 'Làm mới trạng thái';\r\n        }\r\n    }\r\n\r\n    function showCheckoutPopup(payload) {\r\n        if (!checkoutModal || !payload) return;\r\n        activeCheckoutOrderCode = payload.orderCode || '';\r\n        setText('[data-checkout-title]', payload.pageTitle || 'Thanh toán đơn hàng');\r\n        setText('[data-checkout-total]', payload.totalAmountText || '');\r\n        setText('[data-checkout-bank]', payload.bankName || '');\r\n        setText('[data-checkout-account-number]', payload.accountNumber || '');\r\n        setText('[data-checkout-account-name]', payload.accountName || '');\r\n        setText('[data-checkout-transfer-content]', payload.transferContent || '');\r\n        setText('[data-checkout-expires]', payload.expiresAtText || 'Không giới hạn');\r\n        setText('[data-checkout-subtotal]', payload.subtotalText || '');\r\n        setText('[data-checkout-discount]', payload.discountAmountText || '');\r\n        setText('[data-checkout-voucher]', payload.promoCode || 'Không áp dụng');\r\n        setText('[data-checkout-summary-total]', payload.totalAmountText || '');\r\n        renderCheckoutItems(payload.items);\r\n        updateCheckoutStatus(payload);\r\n\r\n        if (checkoutQrImage) {\r\n            checkoutQrImage.hidden = !payload.qrImageUrl;\r\n            checkoutQrImage.src = payload.qrImageUrl || '';\r\n        }\r\n        if (checkoutQrFallback) {\r\n            checkoutQrFallback.hidden = Boolean(payload.qrImageUrl);\r\n        }\r\n\r\n        if (checkoutConfirm) checkoutConfirm.hidden = !payload.isPaid;\r\n        checkoutModal.hidden = false;\r\n        document.body.style.overflow = 'hidden';\r\n        window.clearInterval(checkoutPollTimer);\r\n        if (!payload.isPaid && activeCheckoutOrderCode) {\r\n            checkoutPollTimer = window.setInterval(() => {\r\n                post({ type: 'refreshOrderCheckoutStatus', orderCode: activeCheckoutOrderCode });\r\n            }, 5000);\r\n        }\r\n    }\r\n\r\n    function closeCheckoutPopup(confirmed = false) {\r\n        window.clearInterval(checkoutPollTimer);\r\n        checkoutPollTimer = 0;\r\n        if (checkoutModal) checkoutModal.hidden = true;\r\n        document.body.style.overflow = '';\r\n        post({ type: confirmed ? 'confirmOrderCheckoutSuccess' : 'closeOrderCheckoutPopup', orderCode: activeCheckoutOrderCode });\r\n    }\r\n\r\n    document.querySelectorAll('[data-checkout-close]').forEach(button => {\r\n        button.addEventListener('click', () => closeCheckoutPopup(false));\r\n    });\r\n\r\n    checkoutRefresh?.addEventListener('click', () => {\r\n        if (!activeCheckoutOrderCode) return;\r\n        checkoutRefresh.disabled = true;\r\n        checkoutRefresh.textContent = 'Đang kiểm tra...';\r\n        post({ type: 'refreshOrderCheckoutStatus', orderCode: activeCheckoutOrderCode });\r\n    });\r\n\r\n    checkoutConfirm?.addEventListener('click', () => closeCheckoutPopup(true));\r\n\r\n    checkoutQrImage?.addEventListener('error', () => {\r\n        checkoutQrImage.hidden = true;\r\n        if (checkoutQrFallback) checkoutQrFallback.hidden = false;\r\n    });\r\n\r\n    window.__nestgHome = { toast: showToast, setCartCount() {} };\r\n    window.__nestgOrderCheckout = { show: showCheckoutPopup, updateStatus: updateCheckoutStatus };\r\n\r\n    window.__nestgLoading = {\r\n        show(title, message) {\r\n            if (!loading) return;\r\n            loading.querySelector('[data-app-loading-title]').textContent = title || 'Đang xử lý';\r\n            loading.querySelector('[data-app-loading-message]').textContent = message || 'Vui lòng chờ trong giây lát.';\r\n            loading.hidden = false;\r\n        },\r\n        hide() { if (loading) loading.hidden = true; }\r\n    };\r\n})();";
	}

	private static string Initial(string? value)
	{
		return Html((string.IsNullOrWhiteSpace(value) ? "N" : value.Trim()).Substring(0, 1).ToUpperInvariant());
	}

	private static string Html(string? value)
	{
		return WebUtility.HtmlEncode(value ?? string.Empty);
	}

	private static string Attr(string? value)
	{
		return WebUtility.HtmlEncode(value ?? string.Empty);
	}
}
